+    }
+
+    void setBody(String body) {
+        this.body = body;
+    }
+
+    MessageStatus status() {
+        return status;
+    }
+
+    void block() {
+        this.status = MessageStatus.BLOCKED;
+    }
+
+    void addCopy(OutboundMessage copy) {
