    50	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
    51	public final class EmailSender {
    52	
    53	    private final SentMessages sentMessages;
    54	    private final List<EmailRule> rules;
    55	
    56	    public EmailSender(SentMessages sentMessages, boolean testMode) {
    57	        this.sentMessages = sentMessages;
    58	        this.rules = List.of(
    59	                new EmailValidationRule(),
    60	                new TestModeRule(testMode),
    61	                new ArchiveCopyRule(testMode)
    62	        );
    63	    }
    64	
    65	    public Message send(String to, String subject, String body) {
    66	        OutboundMessage message = new OutboundMessage(to, subject, body);
    67	        for (EmailRule rule : rules) {
    68	            rule.apply(message);
    69	        }
    70	        Message primary = sentMessages.add("EMAIL", message.to(), message.subject(), message.body(), message.status());
    71	        for (OutboundMessage copy : message.copies()) {
    72	            sentMessages.add("EMAIL", copy.to(), copy.subject(), copy.body(), copy.status());
    73	        }
    74	        return primary;
    75	    }
    76	}
